/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 8
 * ("Remove `ignoreBuildErrors: true`").
 *
 * Mirrors the Phase 0 / Phase 1 / Phase 3 / Phase 4 / Phase 6 / Phase 7
 * files in style: file-content regression guards plus a verification
 * gate that invokes the same build command CI runs.
 *
 * Background (per `measure/tracks/ci_typecheck_alignment_20260603/spec.md`
 * FR-8 and `test-strategy.md` §1 row P8 / §4 architecture guardrails):
 *
 *   - `apps/science-advantage/next.config.ts:25` currently reads
 *     `ignoreBuildErrors: true,` (verified 2026-06-07). The setting was
 *     retained post-Prisma-removal as a workaround for ~370 tsc errors
 *     across 6 root causes. Phases 0–7 of this track resolved those root
 *     causes; the only remaining work is the cosmetic cleanup of the
 *     setting itself plus the 9-line comment block that enumerates the
 *     (now-resolved) error cohorts.
 *   - Per `test-strategy.md` §1 P8: "the diff is 1 character
 *     (`true → false`) plus comment cleanup. Build must pass *before*
 *     the flip is committed (sequence the commits: typecheck-clean
 *     first, then flip, then build)."
 *   - Per `test-strategy.md` §4 architecture guardrails: "No new
 *     `ignoreBuildErrors` anywhere in `apps/**` or `packages/**`. Add
 *     a `doctor` rule (or grep guard in CI) that fails if any
 *     `next.config.{ts,js,mjs}` contains `ignoreBuildErrors: true`
 *     after this track lands."
 *
 * The Phase 8 end-state contract is two-part:
 *
 *   (a) **File content** — `apps/science-advantage/next.config.ts` no
 *       longer contains `ignoreBuildErrors: true` (the value is `false`
 *       or the line is removed entirely), and the 9-line resolved-
 *       error enumeration comment block is collapsed to a one-liner
 *       (or removed). A regression that re-introduces
 *       `ignoreBuildErrors: true` must surface immediately per the §4
 *       guardrail above.
 *   (b) **End-to-end build gate** — `pnpm turbo run build
 *       --filter=science-advantage` exits 0 with the new tsc-clean
 *       code, per `test-strategy.md` §1 P8. With `ignoreBuildErrors:
 *       true` masking the residual tsc errors, the build currently
 *       exits 0; this is a forward-looking smoke test that locks the
 *       build state so the post-flip state does not regress.
 *
 * Tests in this file:
 *
 *   1. `apps/science-advantage/next.config.ts does not contain
 *      'ignoreBuildErrors: true'` — **red-phase assertion** (fails
 *      today; line 25 still reads `ignoreBuildErrors: true,`).
 *   2. `next.config.ts: if 'ignoreBuildErrors' is present, the value
 *      equals 'false' (not 'true')` — **red-phase assertion** (fails
 *      today; the value is `true`).
 *   3. `next.config.ts: the resolved-error enumeration comment block
 *      is removed` — **red-phase assertion** (fails today; the phrase
 *      "tsc blockers are pre-existing and out of scope" is still
 *      present on line 16, anchoring the 9-line bullet list).
 *   4. `next.config.ts: no pre-resolution 'Retained post-Prisma-
 *      removal' annotation` — **red-phase assertion** (fails today;
 *      line 15 still references the prisma_drizzle_science_controllers
 *      track as the rationale for the masking).
 *   5. `pnpm turbo run build --filter=science-advantage completed
 *      (sanity check on shared setup)` — **green-phase guard** (passes
 *      today; the build exits 0 because `ignoreBuildErrors: true`
 *      masks tsc errors. Locks the build state so a future flip of
 *      `ignoreBuildErrors: true → false` cannot silently regress the
 *      build).
 *   6. `pnpm turbo run build --filter=science-advantage exits 0 (end-
 *      to-end gate)` — **green-phase guard** (passes today per §1 P8
 *      build-gate contract; locks the build state).
 *
 * Performance note: `pnpm turbo run build --filter=science-advantage`
 * can take several minutes (Next.js production build). To keep the
 * test file under the supervisor role-timeout budget, we run the build
 * once via `beforeAll` and cache the output, then run all assertions
 * against the cached strings. This is the same pattern used in
 * `phase-7-check-types-script.test.ts` (which runs `tsc --noEmit` via
 * `beforeAll`).
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import {
  spawnSync,
  type SpawnSyncReturns,
} from "node:child_process";
import { beforeAll, describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();

/**
 * Unique phrases that identify the resolved-error enumeration comment
 * block in `next.config.ts`. The block lists the tsc error cohorts
 * that have all been resolved by Phases 0–7 (~333 testing-library
 * matcher narrowing, INTERN role widening, missing sibling modules,
 * ProcessEnv narrowing, duplicate next@16 type identities, misc).
 * Once the comment is collapsed to a one-liner (or removed), these
 * phrases no longer appear. Anchored to the 2026-06-07 file state.
 */
const RESOLVED_ERROR_COMMENT_PHRASE =
  "tsc blockers are pre-existing and out of scope";
const PRISMA_REMOVAL_PHRASE = "Retained post-Prisma-removal";
/**
 * Bullet-item phrases that uniquely identify the resolved-cohort
 * enumeration. Any one of these being present means the comment
 * block is still expanded.
 */
const RESOLVED_COHORT_BULLETS = [
  "testing-library matcher narrowing (toBeInTheDocument et al.)",
  "INTERN role widening in lib/auth/session.ts",
  "Missing sibling modules lib/auth/{password,rate-limit}.test.ts",
  "ProcessEnv narrowing in vitest.integration",
  "Duplicate next@16 type identities: RequestInit / CurriculumUnitSummary",
  "Misc: user-menu string|null, beforeEach import, xp.test comparison, mastery-profile overload",
] as const;

/**
 * Module-scoped cache for the `pnpm turbo run build
 * --filter=science-advantage` spawn result. Populated once by the
 * second describe block's `beforeAll`; read by tests 5 and 6. Sharing
 * the expensive build invocation across tests is the difference
 * between a ~3-min test run and a ~15-min test run. Scoping the
 * beforeAll inside the second describe (rather than at the file
 * level) means `vitest run -t "file-content"` skips the build
 * entirely, so the targeted Red-phase command in `package.json`
 * scripts (`pnpm --filter science-advantage exec vitest run --config
 * vitest.unit.config.ts lib/ci-gates/phase-8-ignore-build-errors.test.ts`)
 * runs in <1s when filtered to the file content tests.
 */
let buildOutput: string;
let buildStatus: number | null;

/**
 * Runs `pnpm turbo run build --filter=science-advantage` and returns
 * the captured result. We pin a 9-minute timeout because `next build`
 * on the science-advantage codebase takes 2-4 minutes; the margin
 * absorbs a cold start and slow CI runners.
 *
 * Invokes `corepack pnpm` so the test works both in dev (where pnpm
 * is provisioned via corepack) and in CI (where pnpm is on PATH and
 * corepack forwards transparently).
 * @returns The captured spawn result.
 */
function runBuildGate(): SpawnSyncReturns<string> {
  return spawnSync(
    "corepack",
    ["pnpm", "turbo", "run", "build", "--filter=science-advantage"],
    {
      cwd: SCIENCE_ADVANTAGE_ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 540_000,
    },
  );
}

describe(
  "Phase 8 remove ignoreBuildErrors (ci_typecheck_alignment_20260603)",
  () => {
    describe(
      "file-content regression guards (red-phase: fail today; flip green when Phase 8 is implemented)",
      () => {
        it("apps/science-advantage/next.config.ts does not contain `ignoreBuildErrors: true`", () => {
          const configPath = resolve(
            SCIENCE_ADVANTAGE_ROOT,
            "next.config.ts",
          );
          expect(
            existsSync(configPath),
            `Expected ${configPath} to exist; the Phase 8.1 task requires this file to be present.`,
          ).toBe(true);
          const content = readFileSync(configPath, "utf8");
          expect(
            /ignoreBuildErrors\s*:\s*true\b/u.test(content),
            `Expected next.config.ts to not contain 'ignoreBuildErrors: true'. ` +
              `Per test-strategy.md \u00a71 P8, the Phase 8 task is to flip ` +
              `\`ignoreBuildErrors: true,\` \u2192 \`ignoreBuildErrors: false,\` ` +
              `(or remove the line). Currently the file still has ` +
              `\`ignoreBuildErrors: true,\` on line 25. Per ` +
              `test-strategy.md \u00a74 architecture guardrails, no new ` +
              `\`ignoreBuildErrors\` may exist anywhere in apps/** or ` +
              `packages/**. File content:\n${content}`,
          ).toBe(false);
        });

        it("next.config.ts: if `ignoreBuildErrors` is present, the value equals `false` (not `true`)", () => {
          const configPath = resolve(
            SCIENCE_ADVANTAGE_ROOT,
            "next.config.ts",
          );
          const content = readFileSync(configPath, "utf8");
          const match = content.match(
            /ignoreBuildErrors\s*:\s*(true|false)\b/u,
          );
          if (match) {
            expect(
              match[1],
              `Expected next.config.ts: if 'ignoreBuildErrors' is present, ` +
                `the value should be 'false' (Phase 8 flip). Found ` +
                `'ignoreBuildErrors: ${match[1]}' on the source line. Per ` +
                `test-strategy.md \u00a74 architecture guardrails, ` +
                `'ignoreBuildErrors: true' is a type-safety hole that may not ` +
                `re-appear after this track lands.`,
            ).toBe("false");
          } else {
            expect(
              /ignoreBuildErrors\s*:/u.test(content),
              `Expected next.config.ts: 'ignoreBuildErrors' is absent, which is ` +
                `acceptable (the Phase 8 end state permits removing the line ` +
                `entirely). If a future contributor re-adds the field, this ` +
                `assertion flips to require the value to be 'false'. ` +
                `File content:\n${content}`,
            ).toBe(false);
          }
        });

        it("next.config.ts: the resolved-error enumeration comment block is removed", () => {
          const configPath = resolve(
            SCIENCE_ADVANTAGE_ROOT,
            "next.config.ts",
          );
          const content = readFileSync(configPath, "utf8");
          expect(
            content.includes(RESOLVED_ERROR_COMMENT_PHRASE),
            `Expected next.config.ts to not contain the resolved-error ` +
              `enumeration comment block. The phrase ` +
              `${JSON.stringify(RESOLVED_ERROR_COMMENT_PHRASE)} identifies ` +
              `the block that lists the tsc error cohorts resolved by ` +
              `Phases 0\u20137. Per test-strategy.md \u00a71 P8, this comment ` +
              `should be collapsed to a one-liner (or removed). ` +
              `File content:\n${content}`,
          ).toBe(false);
          for (const bullet of RESOLVED_COHORT_BULLETS) {
            expect(
              content.includes(bullet),
              `Expected next.config.ts to not contain the resolved-cohort ` +
                `bullet ${JSON.stringify(bullet)}. Per test-strategy.md ` +
                `\u00a71 P8, the entire enumeration must be collapsed. ` +
                `File content:\n${content}`,
            ).toBe(false);
          }
        });

        it("next.config.ts: no pre-resolution 'Retained post-Prisma-removal' annotation", () => {
          const configPath = resolve(
            SCIENCE_ADVANTAGE_ROOT,
            "next.config.ts",
          );
          const content = readFileSync(configPath, "utf8");
          expect(
            content.includes(PRISMA_REMOVAL_PHRASE),
            `Expected next.config.ts to not contain ` +
              `${JSON.stringify(PRISMA_REMOVAL_PHRASE)}. This phrase ` +
              `anchors the resolved-error enumeration block (line 15 of the ` +
              `current file). Once Phase 8 collapses the comment to a ` +
              `one-liner (or removes it), this phrase no longer appears. ` +
              `File content:\n${content}`,
          ).toBe(false);
        });
      },
    );

    describe(
      "end-to-end build gate (green-phase: passes today because `ignoreBuildErrors: true` masks tsc errors; locks the build state)",
      () => {
        beforeAll(() => {
          const result = runBuildGate();
          buildOutput = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
          buildStatus = result.status;
        }, 600_000);

        it("pnpm turbo run build --filter=science-advantage completed (sanity check on shared setup)", () => {
          // If the build was killed by the spawn timeout (status null)
          // or threw an unexpected exit code, the assertion below would
          // silently pass on an empty buildOutput. This guard makes
          // that failure mode loud.
          expect(
            buildStatus,
            `Expected pnpm turbo run build --filter=science-advantage to ` +
              `exit; got status ${String(buildStatus)}. First 1 KB of ` +
              `output:\n${buildOutput.slice(0, 1024)}`,
          ).not.toBeNull();
        });

        it("pnpm turbo run build --filter=science-advantage exits 0 (end-to-end gate)", () => {
          // Per test-strategy.md §1 P8: "Build must pass *before* the
          // flip is committed (sequence the commits: typecheck-clean
          // first, then flip, then build)." Currently passes because
          // `ignoreBuildErrors: true` masks tsc errors during the
          // build. Locks the build state so a future flip of
          // `ignoreBuildErrors: true → false` does not regress the
          // build (the post-flip state will only stay green if Phases
          // 0–7 left tsc clean, which is their contract).
          expect(
            buildStatus,
            `Expected pnpm turbo run build --filter=science-advantage to ` +
              `exit 0 (the Phase 8 end-state gate from test-strategy.md ` +
              `\u00a71 P8). Currently exits with code ${String(buildStatus)}. ` +
              `First 4 KB of output:\n${buildOutput.slice(0, 4096)}`,
          ).toBe(0);
        });
      },
    );
  },
);

/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 0.
 *
 * These tests are NOT unit tests of any application code. They are gate-level
 * regression guards that invoke the same `pnpm --filter science-advantage`
 * scripts that CI runs, and assert each gate exits 0.
 *
 * Phase 0 baseline (verified 2026-06-06, see
 * `measure/tracks/ci_typecheck_alignment_20260603/test-strategy.md` §0):
 *   - `pnpm --filter science-advantage check-types` exits non-zero with
 *     617 tsc errors (TS2339=347, TS2769=225, TS2741=12, TS2345=9, TS2322=7,
 *     TS2305=5, others=12). ~287 of the TS2339 cohort is jest-dom matcher
 *     narrowing suppressed by a multi-version vitest split (see §0).
 *   - `pnpm --filter science-advantage lint` exits non-zero with
 *     4 errors + 6 warnings. 4 are `react-hooks/immutability` in
 *     `components/features/teacher/analytics/student-lesson-detail-analytics.tsx`,
 *     6 are `@typescript-eslint/no-unused-vars` in
 *     `lib/gamification/badges.ts`.
 *   - `Role` from `@reading-advantage/auth` already includes `INTERN`
 *     (widened in `packages/auth/src/roles.ts`); coordination with Track 3
 *     (Argon2id + Auth Flatten) is intact.
 *
 * Both gate tests are expected to fail in the Red phase. The Track 3
 * coordination test is expected to pass and serves as a regression guard
 * for the canonical role source.
 */

import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { describe, it, expect } from "vitest";
import { ROLES, type Role } from "@reading-advantage/auth";

/**
 * Runs a pnpm command in the science-advantage package and returns the
 * captured result. We pin a 9-minute per-gate timeout because `tsc --noEmit`
 * on a 4k-line project takes several minutes; lint is usually <30s.
 *
 * Invokes `corepack pnpm` so the test works both in dev (where pnpm is
 * provisioned via corepack) and in CI (where pnpm is on PATH and corepack
 * forwards transparently).
 * @param args Arguments passed to `pnpm`.
 * @returns The captured spawn result.
 */
function runGate(args: readonly string[]): SpawnSyncReturns<string> {
  return spawnSync("corepack", ["pnpm", ...args], {
    cwd: process.cwd(),
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 540_000,
  });
}

const GATE_TIMEOUT_MS = 600_000;

describe("Phase 0 ci-gates (ci_typecheck_alignment_20260603)", () => {
  it(
    "check-types exits 0 (science-advantage type-clean)",
    { timeout: GATE_TIMEOUT_MS },
    () => {
      const result = runGate(["--filter", "science-advantage", "check-types"]);
      const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
      // Baseline expectation (Red phase): non-zero exit with 617 errors.
      // Track exit code, stdout, and stderr in the failure message so the
      // gate's failure mode is debuggable from the test report.
      expect(
        result.status,
        `pnpm --filter science-advantage check-types exited with code ${String(
          result.status,
        )}. Output:\n${output}`,
      ).toBe(0);
    },
  );

  it(
    "lint exits 0 (science-advantage lint-clean)",
    { timeout: GATE_TIMEOUT_MS },
    () => {
      const result = runGate(["--filter", "science-advantage", "lint"]);
      const output = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
      // Baseline expectation (Red phase): non-zero exit with 4 errors
      // and 6 warnings.
      expect(
        result.status,
        `pnpm --filter science-advantage lint exited with code ${String(
          result.status,
        )}. Output:\n${output}`,
      ).toBe(0);
    },
  );

  it(
    "Role type from @reading-advantage/auth includes INTERN (Track 3 coordination baseline)",
    () => {
      // This test guards the canonical role source that Track 3
      // (Argon2id + Auth Flatten) will preserve. If the `Role` union
      // ever narrows to drop INTERN, this test fails at type-check time
      // and we have lost the intern-role widening this track depends on.
      const role: Role = ROLES.INTERN;
      expect(role).toBe("INTERN");
      expect(ROLES.INTERN).toBe("INTERN");
    },
  );
});

/**
 * Red-phase gate tests for track `ci_typecheck_alignment_20260603` / Phase 7
 * ("Add `check-types` Script").
 *
 * Mirrors the Phase 0 / Phase 1 / Phase 3 / Phase 4 / Phase 6 files in style:
 * file-content regression guards plus a verification gate that spawns the same
 * `pnpm --filter science-advantage check-types` invocation CI runs, and
 * asserts the post-Phase-7 end state.
 *
 * Background (per `measure/tracks/ci_typecheck_alignment_20260603/spec.md`
 * FR-7 and `test-strategy.md` §0 / §1 P7 / §5 P7 notes):
 *
 *   - `apps/science-advantage/package.json:14` already declares the
 *     `"check-types": "tsc --noEmit"` script (added in commit `c1e77f9`,
 *     "feat(science-advantage): add check-types script for Phase 6 quality
 *     gate"). Phase 7 is therefore framed as a *verification* phase, not a
 *     fix-it phase.
 *   - The workspace-root `turbo.json:25-27` declares the `check-types` task
 *     with `dependsOn: ["^check-types"]`, so `pnpm turbo run check-types
 *     --filter=science-advantage` resolves to the script (not a skip).
 *   - The end-state gate (per `test-strategy.md` §1 P7):
 *     `pnpm turbo run check-types --filter=science-advantage` resolves to
 *     the script **and** the script invokes `tsc --noEmit` (not a no-op,
 *     not a `tsc` build, not a `pnpm echo` shim).
 *
 * The Phase 7 end-state contract is two-part:
 *
 *   (a) **Wiring integrity** — the script is declared, non-empty, references
 *       `tsc`, includes `--noEmit`, and turbo can resolve it via the
 *       `check-types` task. A regression that deletes the script, replaces
 *       it with a no-op (`echo done`, `:`, `true`, `pnpm echo`, ...), or
 *       drops the `tsc` / `--noEmit` flags must surface immediately.
 *   (b) **End-to-end gate** — `pnpm --filter science-advantage check-types`
 *       exits 0 **and** the output contains tsc-specific patterns (not a
 *       no-op's empty / `done` echo). This gate fails today (post-Phase-6
 *       tsc error count is 265, so `tsc --noEmit` exits 2); it will flip to
 *       green once Phases 0–6 are all resolved.
 *
 * Performance note: `pnpm --filter science-advantage check-types` spawns
 * `tsc --noEmit` which takes ~30s. To keep the test file under the
 * supervisor role-timeout budget, we run the command once via `beforeAll`
 * and cache the output, then run all 7 assertions against the cached
 * strings. This is the same pattern used in
 * `phase-4-process-env-cast.test.ts` and `phase-6-misc-cleanup.test.ts`.
 *
 * Tests in this file:
 *
 *   1. `apps/science-advantage/package.json declares a check-types script`
 *      — **regression guard** (passes today; locks the script declaration
 *      so a future deletion surfaces immediately).
 *   2. `check-types script value is non-empty (catches no-op regression)`
 *      — **regression guard** (passes today; locks the script value
 *      against being replaced with `""`, `:` — an empty / no-op shell
 *      would let turbo silently succeed with no tsc output).
 *   3. `check-types script references tsc (catches non-tsc replacement)`
 *      — **regression guard** (passes today; locks the `tsc` invocation
 *      so a future replacement with `pnpm echo` or `eslint .` is caught).
 *   4. `check-types script includes --noEmit flag (catches tsc build invocation)`
 *      — **regression guard** (passes today; locks the `--noEmit` flag
 *      so a future replacement with bare `tsc` (which would emit `.d.ts`
 *      files into the project) is caught).
 *   5. `turbo.json declares a check-types task with dependsOn ["^check-types"]`
 *      — **regression guard** (passes today; locks turbo's task declaration
 *      so a future rename / dependency-drop surfaces immediately).
 *   6. `pnpm --filter science-advantage check-types output contains tsc invocation evidence (not a no-op)`
 *      — **verification gate** (passes today; the script invokes `tsc
 *      --noEmit` which produces `error TS\d+:` lines. The companion to
 *      test 7: even when the gate exits non-zero, the output must look
 *      like a tsc run, not a no-op's empty echo).
 *   7. `pnpm --filter science-advantage check-types exits 0 (end-to-end gate)`
 *      — **red-phase assertion** (fails today; tsc reports 265 errors so
 *      exit code is 2. This is the precise Phase 7 gate — it will flip to
 *      green once Phases 0–6 are all resolved and tsc reports 0 errors).
 */

import { readFileSync, existsSync } from "node:fs";
import { resolve } from "node:path";
import { spawnSync, type SpawnSyncReturns } from "node:child_process";
import { beforeAll, describe, it, expect } from "vitest";

const SCIENCE_ADVANTAGE_ROOT = process.cwd();
const WORKSPACE_ROOT = resolve(SCIENCE_ADVANTAGE_ROOT, "..", "..");

/**
 * The set of well-known no-op shell invocations a contributor might
 * accidentally paste into the `check-types` script field. The
 * `test-strategy.md` §1 P7 gate explicitly calls out the "not a no-op"
 * failure mode (`pnpm turbo run check-types --filter=science-advantage
 * resolves to the script, not a no-op`). This list is the test-side
 * mirror of that contract.
 */
const NO_OP_SCRIPT_VALUES = [
  "",
  ":",
  "true",
  "false",
  "echo",
  "echo done",
  "exit 0",
  "pnpm echo",
  "pnpm echo done",
] as const;

/**
 * Module-scoped cache for the `pnpm --filter science-advantage
 * check-types` spawn result. Populated once by `beforeAll`; read by
 * tests 6 and 7. Sharing the expensive tsc invocation across tests is
 * the difference between a ~30s test run and a ~120s test run.
 */
let checkTypesOutput: string;
let checkTypesStatus: number | null;

/**
 * Runs `pnpm --filter science-advantage check-types` and returns the
 * captured result. We pin a 9-minute timeout because `tsc --noEmit` on
 * the science-advantage codebase takes several minutes; the margin
 * absorbs a cold start.
 *
 * Invokes `corepack pnpm` so the test works both in dev (where pnpm is
 * provisioned via corepack) and in CI (where pnpm is on PATH and
 * corepack forwards transparently).
 * @returns The captured spawn result.
 */
function runCheckTypesGate(): SpawnSyncReturns<string> {
  return spawnSync(
    "corepack",
    ["pnpm", "--filter", "science-advantage", "check-types"],
    {
      cwd: SCIENCE_ADVANTAGE_ROOT,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      timeout: 540_000,
    },
  );
}

/**
 * Filters raw `tsc --noEmit` output to lines that report any
 * `error TS<num>: <message>`. This is the canonical tsc-invocation
 * evidence pattern: a no-op script (echo / : / true / pnpm echo)
 * would produce empty output or a single `done` line, neither of
 * which matches this regex. The companion to the file-content guards
 * (tests 1–5) — together they form the Phase 7 "not a no-op" gate.
 * @param output The combined stdout/stderr from the spawned pnpm gate.
 * @returns The matching error lines, in the order tsc reported them.
 */
function tscErrorLines(output: string): string[] {
  return output
    .split("\n")
    .filter((line) => /\berror TS\d+:/u.test(line));
}

beforeAll(() => {
  const result = runCheckTypesGate();
  checkTypesOutput = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
  checkTypesStatus = result.status;
}, 600_000);

describe(
  "Phase 7 add check-types script (ci_typecheck_alignment_20260603)",
  () => {
    describe("regression guards (file-content checks; lock the install state)", () => {
      it("apps/science-advantage/package.json declares a check-types script", () => {
        const pkgPath = resolve(SCIENCE_ADVANTAGE_ROOT, "package.json");
        expect(
          existsSync(pkgPath),
          `Expected ${pkgPath} to exist; the Phase 7.1 task requires this file to be present.`,
        ).toBe(true);
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8")) as {
          scripts?: Record<string, string>;
        };
        const script = pkg.scripts?.["check-types"];
        expect(
          script,
          `Expected ${pkgPath} to declare a 'check-types' script so ` +
            `\`pnpm --filter science-advantage check-types\` (and the turbo ` +
            `\`check-types\` task) resolves to a real tsc invocation, not a ` +
            `turbo skip. The \`scripts\` block currently is:\n` +
            `${JSON.stringify(pkg.scripts, null, 2)}`,
        ).toBeDefined();
      });

      it("check-types script value is non-empty (catches no-op regression)", () => {
        const pkgPath = resolve(SCIENCE_ADVANTAGE_ROOT, "package.json");
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8")) as {
          scripts?: Record<string, string>;
        };
        const script = pkg.scripts?.["check-types"] ?? "";
        expect(
          script.trim(),
          `Expected the 'check-types' script value to be a non-empty ` +
            `string so it invokes a real command, not a shell no-op. ` +
            `An empty string, ':', or a pure 'echo' / 'true' / 'false' ` +
            `would let turbo silently succeed with no tsc output. Found: ` +
            `${JSON.stringify(script)}`,
        ).not.toBe("");
        expect(
          NO_OP_SCRIPT_VALUES,
          `Expected 'check-types' script value to not match any known ` +
            `no-op shell invocation. Found: ${JSON.stringify(script)} ` +
            `(matches one of: ${NO_OP_SCRIPT_VALUES.map((v) => JSON.stringify(v)).join(", ")}). ` +
            `Per test-strategy.md §1 P7, the gate is: 'pnpm turbo run ` +
            `check-types --filter=science-advantage resolves to the ` +
            `script, not a no-op.'`,
        ).not.toContain(script);
      });

      it("check-types script references tsc (catches non-tsc replacement)", () => {
        const pkgPath = resolve(SCIENCE_ADVANTAGE_ROOT, "package.json");
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8")) as {
          scripts?: Record<string, string>;
        };
        const script = pkg.scripts?.["check-types"] ?? "";
        expect(
          /\btsc\b/u.test(script),
          `Expected the 'check-types' script to reference the TypeScript ` +
            `compiler (\`tsc\`) so it actually type-checks the project. ` +
            `A replacement with \`pnpm echo\`, \`eslint .\`, or any other ` +
            `non-tsc command would silently bypass the typecheck. Found: ` +
            `${JSON.stringify(script)}`,
        ).toBe(true);
      });

      it("check-types script includes --noEmit flag (catches tsc build invocation)", () => {
        const pkgPath = resolve(SCIENCE_ADVANTAGE_ROOT, "package.json");
        const pkg = JSON.parse(readFileSync(pkgPath, "utf8")) as {
          scripts?: Record<string, string>;
        };
        const script = pkg.scripts?.checkTypes ?? pkg.scripts?.["check-types"] ?? "";
        // The JSON key is `check-types` (hyphenated); the above fallback
        // covers the unlikely camelCase alias.
        const resolved =
          pkg.scripts?.["check-types"] ?? pkg.scripts?.checkTypes ?? "";
        expect(
          resolved,
          `Expected the 'check-types' script to be defined. Found: ${JSON.stringify(resolved)}`,
        ).toBeTruthy();
        expect(
          /--noEmit\b/u.test(resolved),
